  int bytes=3840000;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);byte[] audio=wave.array();
  server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread serving=new Thread(()->{while(!server.isClosed())try{Socket socket=server.accept();Thread client=new Thread(()->{try(Socket c=socket){BufferedReader in=new BufferedReader(new InputStreamReader(c.getInputStream()));String line;while((line=in.readLine())!=null&&!line.isEmpty()){}OutputStream out=c.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: "+audio.length+"\r\nConnection: close\r\n\r\n").getBytes());out.write(audio);out.flush();}catch(Exception ignored){}});client.setDaemon(true);client.start();}catch(Exception ignored){}});serving.setDaemon(true);serving.start();
  String base="http://127.0.0.1:"+server.getLocalPort();JSONObject a=new JSONObject().put("name","Vietnam A").put("type","radio").put("country","VN").put("region","INT").put("url",base+"/a.wav"),b=new JSONObject(a.toString()).put("name","Vietnam B").put("url",base+"/b.wav"),us=new JSONObject(a.toString()).put("name","United States").put("country","US").put("url",base+"/us.wav"),tw=new JSONObject(a.toString()).put("name","Taiwan").put("country","TW").put("region","TW").put("url",base+"/tw.wav");
  ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"JAMPlayer-QueueTest-"+System.currentTimeMillis()+".wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/JAMPlayerQueueTest");local=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(local)){out.write(audio);}values.put(MediaStore.Audio.Media.DISPLAY_NAME,"JAMPlayer-QueueTest-B-"+System.currentTimeMillis()+".wav");otherLocal=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(otherLocal)){out.write(audio);}JSONObject song=new JSONObject().put("name","Music A").put("type","local").put("path",local.toString()),songB=new JSONObject(song.toString()).put("name","Music B").put("path",otherLocal.toString());
